"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16992"],{87329(e){e.exports=JSON.parse('{"id":"FIN-1178","slug":"registered-investment-adviser","term":"Registered Investment Adviser","also_known_as":[],"difficulty":"Advanced","definition":"A registered investment adviser is a firm or individual in the United States that provides investment advice for a fee and is registered with the Securities and Exchange Commission or a state securities regulator.","explanation":["Registered investment advisers, often called RIAs, are regulated mainly under the Investment Advisers Act of 1940. Larger advisers register with the Securities and Exchange Commission, while smaller ones usually register with the state where they operate.","RIAs owe their clients a fiduciary duty, which means they must act in the client\'s best interest, disclose conflicts of interest and seek the best execution for trades. They must provide clients with a disclosure document describing their services, fees, conflicts and disciplinary history.","For example, a financial planner who charges clients a percentage of the assets they manage, or a flat fee for a financial plan, would typically be registered as an investment adviser.","RIAs differ from broker-dealers, who are generally paid through commissions and held to a best-interest standard when making recommendations to retail customers. Many professionals are dually registered. Other countries regulate investment advisers differently; in the United Kingdom, for example, advisers must be authorised by the Financial Conduct Authority."],"note":"","total":1500,"prev":{"slug":"refundable-tax-credit","term":"Refundable Tax Credit"},"next":{"slug":"regression-analysis","term":"Regression Analysis"}}')}}]);